input.content:
package erratum

// Use opens a resource with opener, calls Frob(input) on it, and closes it
// exactly once in all cases. Transient open errors are retried; panics from
// Frob are recovered, Defrob is called for FrobError panics, and the error is
// returned.
func Use(opener ResourceOpener, input string) error {
	var res Resource
	for {
		var err error
		res, err = opener()
		if err == nil {
			break
		}
		if _, ok := err.(TransientError); !ok {
			return err
		}
	}

	var result error
	defer func() {
		if r := recover(); r != nil {
			if fe, ok := r.(FrobError); ok {
				res.Defrob(fe.defrobTag)
			}
			if e, ok := r.(error); ok {
				result = e
			} else {
				panic(r)
			}
		}
		res.Close()
	}()

	res.Frob(input)
	return result
}

